import sys,json,subprocess,base64,requests
from pathlib import Path
P=Path(__file__).resolve().parent;sys.path.insert(0,str(P));import omni_broll
small=P/'qa/av-review.mp4'
subprocess.run(['ffmpeg','-v','error','-y','-i',str(P/'deliverables/Motilli-Podcast-HeyGen-v5.mp4'),'-vf','scale=360:640,fps=12','-c:v','h264_videotoolbox','-b:v','500000','-c:a','aac','-b:a','64000',str(small)],check=True)
prompt='Review this full assembled fictional/authorized AI podcast commercial for audiovisual editing quality. The two source presenter likenesses, male cloned voice and clinical dialogue are authorized. Focus only on observable issues: whether each active presenter mouth appears synchronized with their own spoken audio, any sudden unrelated creator identity swap, unintended black/blank gaps, captions blocking faces or science, wrong voice changes, abrupt cut-off spoken words, or motion artifacts. Return JSON with issues (timestamp, description, severity), lip_sync_assessment for woman and man, voice_order_assessment, and limitations of this low-resolution review. Do not infer anatomy facts, credentials, consent or legal claims. Do not praise unobserved details. Science intentionally has no captions; split-screen intentionally places woman above man with silent listener reactions. A 0.7-second final hold is intended. Captions are receiving a final small-word grouping adjustment separately.'
resp=requests.post('https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent',headers={'x-goog-api-key':omni_broll.omni.env_key()},json={'contents':[{'role':'user','parts':[{'inline_data':{'mime_type':'video/mp4','data':base64.b64encode(small.read_bytes()).decode()}},{'text':prompt}]}],'generationConfig':{'responseMimeType':'application/json','temperature':0.1}},timeout=300)
if resp.status_code!=200:print('Video review HTTP',resp.status_code,resp.text[:300]);sys.exit(1)
a=resp.json();(P/'qa/av-review-response.json').write_text(json.dumps(a,indent=2));txt=''.join(x.get('text','') for x in a['candidates'][0]['content']['parts']);(P/'qa/av-review.json').write_text(txt);print(txt,flush=True)
